style.css:
@-moz-document domain("pinterest.com") {
/* Change all text to pink */
    body, span, a, p, h1, h2, h3, h4, h5, h6, div {
        color: #ffcadd !important;
    }

    /* Change all icons to pink */
    .Icon, svg, path {
        fill: #ffcadd !important;
        stroke: #ffcadd !important;
    }

    /* Change the Save Pin button background to pink */
    .PinButton--save {
        background-color: #ffcadd !important;
    }

    /* Keep the Save Pin button text white */
    .PinButton--save .Button__text {
        color: white !important;
    }

    /* Ensure the background stays white */
    body {
        background-color: white !important;
    }

    /* Hover effect on the save button */
    .PinButton--save:hover {
        background-color: #f7a0c1 !important; /* Lighter pink on hover */
    }
}
